-- Generert av scripts/seed-build.ts fra src/data/*.json. Ikke rediger for hånd:
-- endre datasettet og kjør `npm run seed:build`.
--
-- Kommuner: Tromsø (5501).
-- Deterministisk (id-er fra naturlige nøkler) og idempotent (upsert på key).
-- Kjøres som postgres eller service_role, ikke med den offentlige nøkkelen.

begin;

-- Kilder
on conflict (key) do update set
  navn = excluded.navn,
  url = excluded.url,
  type = excluded.type,
  lisens = excluded.lisens;

-- Kommuner
on conflict (slug) do update set
  kommunenr = excluded.kommunenr,
  navn = excluded.navn,
  fylkesnr = excluded.fylkesnr,
  fylke = excluded.fylke,
  sammenstilt = excluded.sammenstilt,
  grunnlag = excluded.grunnlag,
  merknad = excluded.merknad;

-- Organisasjoner
on conflict (key) do update set
  orgnr = excluded.orgnr,
  navn = excluded.navn,
  kortnavn = excluded.kortnavn,
  nivaa = excluded.nivaa,
  organtype = excluded.organtype,
  overordnet_id = excluded.overordnet_id,
  kommunenr = excluded.kommunenr,
  fylkesnr = excluded.fylkesnr,
  rekkevidde = excluded.rekkevidde,
  myndighet = excluded.myndighet,
  antall_medlemmer = excluded.antall_medlemmer,
  gyldig_fra = excluded.gyldig_fra,
  gyldig_til = excluded.gyldig_til,
  status = excluded.status,
  sensitiv = excluded.sensitiv,
  beskrivelse = excluded.beskrivelse,
  kilde_id = excluded.kilde_id,
  verifisering = excluded.verifisering,
  per = excluded.per,
  merknad = excluded.merknad
where organisasjon.verifisering <> 'verifisert';

-- Organene i hver kommune
delete from kommune_org where kommune_id in (intern.nokkel_id('kommune', 'tromso'));

-- Segmenter
on conflict (kode) do update set
  navn = excluded.navn;

-- Segmentene organene påvirker
delete from org_segment where org_id in (select id from organisasjon where key in ('akvaplan-niva', 'alfheim-stadion-ii', 'arbeidstilsynet', 'arktisk-rads-sekretariat', 'arnestedet-eiendom', 'arnestedet-naeringseiendom', 'aurora-kino', 'avinor', 'consto-as', 'consto-holding-as', 'datatilsynet', 'direktoratet-for-mineralforvaltning', 'finanstilsynet', 'finnmark-fylkeskommune', 'fiskeridirektoratet', 'fjuel-as', 'fjuel-tromso-as', 'forbrukertilsynet', 'forsvaret', 'grotsund-industripark', 'halogaland-jordskifterett', 'halogaland-lagmannsrett', 'havforskningsinstituttet', 'helse-nord-rhf', 'helse-og-velferdsutvalget', 'husbanken', 'innovasjon-norge-arktis', 'karlsoy-kommune', 'kartverket', 'kofa', 'kommunal-og-distriktsdepartementet', 'kommune-og-byutviklingsutvalget', 'konkurransetilsynet', 'ks-troms', 'kystverket-troms-og-finnmark', 'leroy-aurora', 'leroy-seafood-group', 'lo-troms', 'ludwig-mack-as', 'macks-olbryggeri', 'mangfolds-og-integreringsutvalget', 'mattilsynet', 'naeringsforeningen-tromsoregionen', 'nav-troms-og-finnmark', 'nav-tromso', 'nergard-as', 'nergard-havfiske', 'nergard-seafood', 'nho-arktis', 'nilu', 'nina', 'nofima', 'nord-troms-og-senja-tingrett', 'nordkraft', 'norges-rafisklag', 'norsk-polarinstitutt', 'norut-norce', 'nve', 'nye-veier', 'oppvekst-og-utdanningsutvalget', 'protromso', 'remiks-husholdning', 'remiks-miljopark', 'remiks-naering', 'ressurs-tromso', 'sametinget', 'sintef', 'sivilforsvaret', 'sivilombudet', 'skatteetaten', 'sparebank-1-gruppen', 'sparebank-1-nord-norge', 'statens-vegvesen', 'statsadvokatene-troms-og-finnmark', 'statsbygg', 'statsforvalteren-troms-og-finnmark', 'stortinget-troms-valgkrets', 'tannhelsetjenesten-troms', 'tg-naeringseiendom-as', 'tolletaten', 'torghatten-nord', 'troms-fylkeskommune', 'troms-fylkeskommune-1838-2019', 'troms-fylkeskommune-administrasjonen', 'troms-fylkeskommune-eldrerad', 'troms-fylkeskommune-kontrollutvalg', 'troms-fylkeskommune-rad-funksjonsnedsettelse', 'troms-fylkesting', 'troms-fylkesutvalg', 'troms-holding', 'troms-kraft', 'troms-og-finnmark-fylkeskommune', 'troms-politidistrikt', 'troms-ungdommens-fylkesrad', 'tromso-administrasjonsutvalget', 'tromso-arbeidsmiljoutvalget', 'tromso-brann-og-redning-kf', 'tromso-eldreradet', 'tromso-formannskap', 'tromso-havn-kf', 'tromso-klageutvalget', 'tromso-kommune', 'tromso-kommune-administrasjonen', 'tromso-kommunestyre', 'tromso-kontrollutvalget', 'tromso-parkering', 'tromso-rad-funksjonsnedsettelse', 'tromso-studentutvalg', 'tromso-ungdomsradet', 'tromsobadet-as', 'tromsobadet-kf', 'tromsobolig-kf', 'uit', 'unn', 'visit-tromso-region'));

-- Personer
on conflict (key) do update set
  navn = excluded.navn;

-- Roller
on conflict (key) do update set
  org_id = excluded.org_id,
  person_id = excluded.person_id,
  tittel = excluded.tittel,
  rolletype = excluded.rolletype,
  status = excluded.status,
  parti = excluded.parti,
  fra = excluded.fra,
  til = excluded.til,
  til_forventet = excluded.til_forventet,
  kilde_id = excluded.kilde_id,
  verifisering = excluded.verifisering,
  per = excluded.per,
  merknad = excluded.merknad
where rolleinnehav.verifisering <> 'verifisert';

-- Relasjoner
on conflict (key) do update set
  fra_org_id = excluded.fra_org_id,
  til_org_id = excluded.til_org_id,
  type = excluded.type,
  andel = excluded.andel,
  belop_nok = excluded.belop_nok,
  fra_dato = excluded.fra_dato,
  til_dato = excluded.til_dato,
  kilde_id = excluded.kilde_id,
  verifisering = excluded.verifisering,
  per = excluded.per,
  merknad = excluded.merknad
where relasjon.verifisering <> 'verifisert';

-- Nøkkeltall
on conflict (key) do update set
  org_id = excluded.org_id,
  aar = excluded.aar,
  periode = excluded.periode,
  type = excluded.type,
  verdi = excluded.verdi,
  enhet = excluded.enhet,
  konsern = excluded.konsern,
  kilde_id = excluded.kilde_id,
  verifisering = excluded.verifisering,
  per = excluded.per,
  merknad = excluded.merknad
where nokkeltall.verifisering <> 'verifisert';

-- Hendelser
on conflict (key) do update set
  dato = excluded.dato,
  presisjon = excluded.presisjon,
  type = excluded.type,
  tittel = excluded.tittel,
  tekst = excluded.tekst,
  org_id = excluded.org_id,
  kommune_id = excluded.kommune_id,
  personer = excluded.personer,
  kilde_id = excluded.kilde_id,
  verifisering = excluded.verifisering,
  per = excluded.per,
  merknad = excluded.merknad
where hendelse.verifisering <> 'verifisert';

-- Beslutningskjeder
on conflict (kommune_id, key) do update set
  tittel = excluded.tittel,
  sporsmal = excluded.sporsmal;
delete from prosess_steg where prosess_id in (intern.nokkel_id('prosess', 'tromso|budsjett'), intern.nokkel_id('prosess', 'tromso|reguleringsplan'));

-- Hull
on conflict (key) do update set
  org_id = excluded.org_id,
  hva = excluded.hva,
  hvorfor = excluded.hvorfor,
  personer = excluded.personer;

commit;
